package stowage

import "testing"

func TestReady(t *testing.T) {
	if !Ready() {
		t.Fatal("baseline not ready")
	}
}

// Package stowage 是本地舱单与配载的本地基线。
package stowage

// Ready 表示基线可以运行。
func Ready() bool { return true }

