1	// Package stowage 提供本地舱单与配载能力：登记舱位和货物，执行装载、
2	// 卸下、移动调整，并查询配载情况。
3	//
4	// 承重与重量均为正整数千克（int64）。编号与目的地在去掉首尾空白后不得
5	// 为空；编号按去空白后的值识别且区分大小写。
6	package stowage
7	
8	import (
9		"errors"
10		"fmt"
11		"sort"
12		"strings"
13		"sync"
14	)
15	
16	// Location 表示一件货物当前所处的位置。
17	type Location struct {
18		// HoldID 为所在舱位编号；货物未装载时为空字符串。
19		HoldID string
20		// Loaded 报告货物是否已装载。
21		Loaded bool
22	}
23	
24	// Unloaded 是未装载位置的规范表示。
25	func Unloaded() Location { return Location{} }
26	
27	// Hold 是舱位信息的独立快照。
28	type Hold struct {
29		ID       string
30		Capacity int64
31		Used     int64
32	}
33	
34	// Remaining 返回舱位剩余承重。
35	func (h Hold) Remaining() int64 { return h.Capacity - h.Used }
36	
37	// CargoInfo 是货物信息的独立快照。
38	type CargoInfo struct {
39		ID          string
40		Weight      int64
41		Destination string
42		// Mixable 表示该货物是否允许与不同目的地的货物共舱。
43		Mixable  bool
44		Location Location
45	}
46	
47	// CargoRef 是清单中的一条货物引用（编号与重量），按编号字典序排列。
48	type CargoRef struct {
49		ID     string
50		Weight int64
51	}
52	
53	// HoldView 是单个舱位的配载视图，为独立快照。
54	type HoldView struct {
55		ID       string
56		Capacity int64
57		Used     int64
58		Cargo    []CargoRef
59	}
60	
61	// Remaining 返回舱位剩余承重。
62	func (v HoldView) Remaining() int64 { return v.Capacity - v.Used }
63	
64	// CargoMove 描述一件货物在一次调整中位置的变化，两者均为规范位置
65	// （未装载时 Location.Loaded 为 false）。
66	type CargoMove struct {
67		CargoID string
68		From    Location
69		To      Location
70	}
71	
72	// HoldWeight 描述一个受影响舱位调整前后的总重量。
73	type HoldWeight struct {
74		HoldID string
75		Before int64
76		After  int64
77	}
78	
79	// AdjustmentResult 是一次成功调整的结果快照。
80	type AdjustmentResult struct {
81		// AdjustmentID 为用户提交调整时使用的编号。
82		AdjustmentID string
83		// Moves 列出每件涉及货物的原位置与新位置，按货物编号字典序排列。
84		Moves []CargoMove
85		// HoldWeights 列出受影响舱位调整前后的重量，按舱位编号字典序排列。
86		HoldWeights []HoldWeight
87	}
88	
89	// Operation 表示单条装卸调整操作。
90	type Operation struct {
91		// Kind 为操作种类：Load（装载）、Unload（卸下）或 Move（移动）。
92		Kind OpKind
93		// CargoID 为货物编号，首尾空白会被去除。
94		CargoID string
95		// TargetHoldID 为目标舱位编号；仅 Load 与 Move 使用，首尾空白会被去除。
96		TargetHoldID string
97	}
98	
99	// OpKind 表示调整操作的种类。
100	type OpKind int
101	
102	const (
103		// Load 将未装载货物装入目标舱位。
104		Load OpKind = iota + 1
105		// Unload 将已装载货物卸下，使其回到未装载状态。
106		Unload
107		// Move 将已装载货物移动到另一个舱位。
108		Move
109	)
110	
111	// String 返回操作种类的文字描述。
112	func (k OpKind) String() string {
113		switch k {
114		case Load:
115			return "load"
116		case Unload:
117			return "unload"
118		case Move:
119			return "move"
120		default:
121			return fmt.Sprintf("invalid(%d)", int(k))
122		}
123	}
124	
125	var (
126		// ErrHoldExists 在重复登记舱位时返回（包装在 *RegistrationError 中）。
127		ErrHoldExists = errors.New("hold already exists")
128		// ErrCargoExists 在重复登记货物时返回（包装在 *RegistrationError 中）。
129		ErrCargoExists = errors.New("cargo already exists")
130		// ErrNotFound 表示查询或调整引用了不存在的舱位或货物。
131		ErrNotFound = errors.New("not found")
132		// ErrInvalidArgument 表示参数不合法（空白编号、非正重量等）。
133		ErrInvalidArgument = errors.New("invalid argument")
134	)
135	
136	// RegistrationError 说明一次登记失败的对象与原因。重复登记时系统保留原
137	// 记录不变，Err 为 ErrHoldExists 或 ErrCargoExists。
138	type RegistrationError struct {
139		Kind string // "hold" 或 "cargo"
140		ID   string // 规范化后的编号
141		Err  error
142	}
143	
144	func (e *RegistrationError) Error() string {
145		return fmt.Sprintf("stowage: %s registration %q: %s", e.Kind, e.ID, e.Err)
146	}
147	
148	func (e *RegistrationError) Unwrap() error { return e.Err }
149	
150	// ReferenceError 描述调整中一条引用了不存在对象的操作。
151	type ReferenceError struct {
152		Kind      string // "hold" 或 "cargo"
153		ID        string
154		Operation OpKind
155	}
156	
157	func (e *ReferenceError) Error() string {
158		return fmt.Sprintf("stowage: %s %q does not exist (operation %s)", e.Kind, e.ID, e.Operation)
159	}
160	
161	func (e *ReferenceError) Is(target error) bool { return target == ErrNotFound }
162	
163	// AdjustmentError 说明一次调整被拒绝的具体原因。涉及的货物或舱位编号会
164	// 在 ID 中给出（终态校验类错误可能涉及多个编号）。
165	type AdjustmentError struct {
166		// Reason 为机器可读的原因代码：
167		// empty、duplicate_operation、invalid_operation、not_loaded、
168		// same_hold、over_capacity、mixed_destination、id_conflict、overflow。
169		Reason string
170		// Kind 为相关对象种类："adjustment"、"cargo"、"hold" 或 "operations"。
171		Kind string
172		// ID 为相关对象编号；多个对象时按字典序排列并以逗号连接。
173		ID string
174		// Err 为底层错误，可能为 ErrInvalidArgument 或 ErrNotFound。
175		Err error
176	}
177	
178	func (e *AdjustmentError) Error() string {
179		switch e.Reason {
180		case "empty":
181			return "stowage: adjustment contains no operations"
182		case "duplicate_operation":
183			return fmt.Sprintf("stowage: cargo %q appears more than once in adjustment", e.ID)
184		case "invalid_operation":
185			return fmt.Sprintf("stowage: operation %s on cargo %q is invalid", e.ID, e.Kind)
186		case "not_loaded":
187			return fmt.Sprintf("stowage: cargo %q is not loaded but operation requires it to be", e.ID)
188		case "same_hold":
189			return fmt.Sprintf("stowage: cargo %q is already in hold %q", e.ID, e.Kind)
190		case "over_capacity":
191			return fmt.Sprintf("stowage: hold %q would exceed its capacity", e.ID)
192		case "mixed_destination":
193			return fmt.Sprintf("stowage: mixed-destination conflict in hold %q", e.ID)
194		case "id_conflict":
195			return fmt.Sprintf("stowage: adjustment %q was already submitted with different content", e.ID)
196		case "overflow":
197			return fmt.Sprintf("stowage: weight computation overflows int64 in hold %q", e.ID)
198		default:
199			return fmt.Sprintf("stowage: adjustment rejected: %s (%s %q)", e.Reason, e.Kind, e.ID)
200		}
201	}
202	
203	func (e *AdjustmentError) Unwrap() error { return e.Err }
204	
205	type holdRec struct {
206		id       string
207		capacity int64
208		used     int64
209		cargo    map[string]int64 // 货物编号 -> 重量
210	}
211	
212	type cargoRec struct {
213		id          string
214		weight      int64
215		destination string
216		mixable     bool
217		hold        string // 空串表示未装载
218	}
219	
220	// System 是本地舱单与配载系统。零值不可用，请使用 New 创建。
221	// 单个 System 的导出方法可被多个 goroutine 同时调用。
222	type System struct {
223		mu       sync.Mutex
224		holds    map[string]*holdRec
225		cargos   map[string]*cargoRec
226		adjusted map[string]AdjustmentResult
227	}
228	
229	// New 创建空的配载系统。
230	func New() *System {
231		return &System{
232			holds:    make(map[string]*holdRec),
233			cargos:   make(map[string]*cargoRec),
234			adjusted: make(map[string]AdjustmentResult),
235		}
236	}
237	
238	func normalizeID(s string) (string, bool) {
239		id := strings.TrimSpace(s)
240		return id, id != ""
241	}
242	
243	// RegisterHold 登记一个舱位。capacity 必须为正整数千克。编号去空白后为
244	// 空、或舱位已存在时返回 *RegistrationError；已存在时原记录保留不变。
245	func (s *System) RegisterHold(id string, capacity int64) error {
246		norm, ok := normalizeID(id)
247		if !ok {
248			return &RegistrationError{Kind: "hold", ID: norm, Err: fmt.Errorf("%w: hold id must not be blank", ErrInvalidArgument)}
249		}
250		if capacity <= 0 {
251			return &RegistrationError{Kind: "hold", ID: norm, Err: fmt.Errorf("%w: capacity must be a positive integer", ErrInvalidArgument)}
252		}
253		s.mu.Lock()
254		defer s.mu.Unlock()
255		if _, exists := s.holds[norm]; exists {
256			return &RegistrationError{Kind: "hold", ID: norm, Err: ErrHoldExists}
257		}
258		s.holds[norm] = &holdRec{id: norm, capacity: capacity, cargo: make(map[string]int64)}
259		return nil
260	}
261	
262	// RegisterCargo 登记一件货物。weight 必须为正整数千克；编号与目的地去
263	// 空白后均不得为空。新登记货物处于未装载状态。货物已存在时返回
264	// *RegistrationError 且原记录保留不变。
265	func (s *System) RegisterCargo(id string, weight int64, destination string, mixable bool) error {
266		norm, ok := normalizeID(id)
267		if !ok {
268			return &RegistrationError{Kind: "cargo", ID: norm, Err: fmt.Errorf("%w: cargo id must not be blank", ErrInvalidArgument)}
269		}
270		if weight <= 0 {
271			return &RegistrationError{Kind: "cargo", ID: norm, Err: fmt.Errorf("%w: weight must be a positive integer", ErrInvalidArgument)}
272		}
273		dest := strings.TrimSpace(destination)
274		if dest == "" {
275			return &RegistrationError{Kind: "cargo", ID: norm, Err: fmt.Errorf("%w: destination must not be blank", ErrInvalidArgument)}
276		}
277		s.mu.Lock()
278		defer s.mu.Unlock()
279		if _, exists := s.cargos[norm]; exists {
280			return &RegistrationError{Kind: "cargo", ID: norm, Err: ErrCargoExists}
281		}
282		s.cargos[norm] = &cargoRec{id: norm, weight: weight, destination: dest, mixable: mixable}
283		return nil
284	}
285	
286	// normOp 是规范化并初步校验后的操作。
287	type normOp struct {
288		kind   OpKind
289		cargo  string
290		target string
291	}
292	
293	// Adjust 执行一次编号为 adjustmentID 的调整，可同时包含多件货物的装载、
294	// 卸下与移动，每件货物至多出现一次。
295	//
296	// 承重与混装限制按全部操作完成后的终态判断；任一操作不合法则整次调整
297	// 不生效。以相同编号和相同内容（操作种类、货物、目标舱位相同，与排列
298	// 顺序无关）重复提交时，直接返回首次成功的结果且不再改变配载；同一编号
299	// 用于不同内容时返回 *AdjustmentError（Reason 为 id_conflict）。失败的
300	// 调整不占用编号。
301	func (s *System) Adjust(adjustmentID string, ops []Operation) (*AdjustmentResult, error) {
302		adjID, ok := normalizeID(adjustmentID)
303		if !ok {
304			return nil, &AdjustmentError{Reason: "invalid_operation", Kind: "adjustment", ID: adjID,
305				Err: fmt.Errorf("%w: adjustment id must not be blank", ErrInvalidArgument)}
306		}
307	
308		normalized := make([]normOp, 0, len(ops))
309		for _, op := range ops {
310			n, err := normalizeOp(op)
311			if err != nil {
312				return nil, &AdjustmentError{Reason: "invalid_operation", Kind: "operations", ID: op.CargoID, Err: err}
313			}
314			normalized = append(normalized, n)
315		}
316	
317		s.mu.Lock()
318		defer s.mu.Unlock()
319	
320		if saved, exists := s.adjusted[adjID]; exists {
321			if sameContent(saved.Moves, normalized) {
322				result := cloneResult(saved)
323				return &result, nil
324			}
325			return nil, &AdjustmentError{Reason: "id_conflict", Kind: "adjustment", ID: adjID}
326		}
327	
328		if len(normalized) == 0 {
329			return nil, &AdjustmentError{Reason: "empty", Kind: "adjustment", ID: adjID}
330		}
331	
332		// 每件货物在一次调整中至多出现一次。
333		seen := make(map[string]bool, len(normalized))
334		for _, op := range normalized {
335			if seen[op.cargo] {
336				return nil, &AdjustmentError{Reason: "duplicate_operation", Kind: "cargo", ID: op.cargo}
337			}
338			seen[op.cargo] = true
339		}
340	
341		// 引用的货物与舱位必须存在。
342		for _, op := range normalized {
343			c, exists := s.cargos[op.cargo]
344			if !exists {
345				return nil, &ReferenceError{Kind: "cargo", ID: op.cargo, Operation: op.kind}
346			}
347			if op.kind == Load || op.kind == Move {
348				if _, exists := s.holds[op.target]; !exists {
349					return nil, &ReferenceError{Kind: "hold", ID: op.target, Operation: op.kind}
350				}
351			}
352			switch op.kind {
353			case Load:
354				if c.hold != "" {
355					return nil, &AdjustmentError{Reason: "invalid_operation", Kind: op.kind.String(), ID: c.id}
356				}
357			case Unload:
358				if c.hold == "" {
359					return nil, &AdjustmentError{Reason: "not_loaded", Kind: "cargo", ID: c.id}
360				}
361			case Move:
362				if c.hold == "" {
363					return nil, &AdjustmentError{Reason: "not_loaded", Kind: "cargo", ID: c.id}
364				}
365				if c.hold == op.target {
366					return nil, &AdjustmentError{Reason: "same_hold", Kind: op.target, ID: c.id}
367				}
368			default:
369				return nil, &AdjustmentError{Reason: "invalid_operation", Kind: "operations", ID: c.id}
370			}
371		}
372	
373		// 在副本上推演终态，保证失败时系统状态原样不变。
374		staging, touched, err := s.buildStaging(normalized)
375		if err != nil {
376			return nil, err
377		}
378	
379		// 校验终态：承重与混装。
380		touchedIDs := make([]string, 0, len(touched))
381		for id := range touched {
382			touchedIDs = append(touchedIDs, id)
383		}
384		sort.Strings(touchedIDs)
385		for _, id := range touchedIDs {
386			h := staging[id]
387			if err := validateHold(h, s.cargos); err != nil {
388				return nil, err
389			}
390		}
391	
392		// 提交：把推演结果写回真实记录。
393		moves := make([]CargoMove, 0, len(normalized))
394		weightBefore := make(map[string]int64, len(touchedIDs))
395		weightAfter := make(map[string]int64, len(touchedIDs))
396		for _, id := range touchedIDs {
397			weightBefore[id] = s.holds[id].used
398			weightAfter[id] = staging[id].used
399		}
400		for _, op := range normalized {
401			c := s.cargos[op.cargo]
402			from := locOf(c.hold)
403			switch op.kind {
404			case Load:
405				s.holds[op.target].cargo[c.id] = c.weight
406			case Unload:
407				delete(s.holds[c.hold].cargo, c.id)
408			case Move:
409				delete(s.holds[c.hold].cargo, c.id)
410				s.holds[op.target].cargo[c.id] = c.weight
411			}
412			c.hold = stagingCargoHold(staging, op)
413			moves = append(moves, CargoMove{CargoID: c.id, From: from, To: locOf(c.hold)})
414		}
415		for _, id := range touchedIDs {
416			s.holds[id].used = staging[id].used
417		}
418		sort.Slice(moves, func(i, j int) bool { return moves[i].CargoID < moves[j].CargoID })
419	
420		weights := make([]HoldWeight, 0, len(touchedIDs))
421		for _, id := range touchedIDs {
422			weights = append(weights, HoldWeight{HoldID: id, Before: weightBefore[id], After: weightAfter[id]})
423		}
424	
425		result := AdjustmentResult{AdjustmentID: adjID, Moves: moves, HoldWeights: weights}
426		// 保存深拷贝快照，使之后的配载变化不影响已存结果。
427		s.adjusted[adjID] = cloneResult(result)
428		return &result, nil
429	}
430	
431	func normalizeOp(op Operation) (normOp, error) {
432		cid, ok := normalizeID(op.CargoID)
433		if !ok {
434			return normOp{}, fmt.Errorf("%w: cargo id must not be blank", ErrInvalidArgument)
435		}
436		n := normOp{kind: op.Kind, cargo: cid}
437		switch op.Kind {
438		case Load, Move:
439			tid, ok := normalizeID(op.TargetHoldID)
440			if !ok {
441				return normOp{}, fmt.Errorf("%w: target hold id must not be blank", ErrInvalidArgument)
442			}
443			n.target = tid
444		case Unload:
445			if strings.TrimSpace(op.TargetHoldID) != "" {
446				return normOp{}, fmt.Errorf("%w: unload takes no target hold", ErrInvalidArgument)
447			}
448		default:
449			return normOp{}, fmt.Errorf("%w: unknown operation kind %d", ErrInvalidArgument, int(op.Kind))
450		}
451		return n, nil
452	}
453	
454	// stagingCargoHold 返回推演后一件操作涉及货物的所属舱位。
455	func stagingCargoHold(staging map[string]*holdRec, op normOp) string {
456		switch op.kind {
457		case Unload:
458			return ""
459		default:
460			return op.target
461		}
462	}
463	
464	// buildStaging 构造受影响舱位的推演副本并应用全部操作，同时完成带溢出
465	// 检查的重量计算。
466	func (s *System) buildStaging(ops []normOp) (map[string]*holdRec, map[string]bool, error) {
467		staging := make(map[string]*holdRec)
468		touched := make(map[string]bool)
469	
470		cloneHold := func(id string) *holdRec {
471			if h, ok := staging[id]; ok {
472				return h
473			}
474			src := s.holds[id]
475			h := &holdRec{id: src.id, capacity: src.capacity, used: src.used, cargo: make(map[string]int64, len(src.cargo))}
476			for cid, w := range src.cargo {
477				h.cargo[cid] = w
478			}
479			staging[id] = h
480			touched[id] = true
481			return h
482		}
483	
484		addWeight := func(h *holdRec, delta int64, cargoID string) error {
485			sum, overflow := addInt64(h.used, delta)
486			if overflow || sum < 0 {
487				return &AdjustmentError{Reason: "overflow", Kind: "hold", ID: h.id}
488			}
489			h.used = sum
490			return nil
491		}
492	
493		for _, op := range ops {
494			c := s.cargos[op.cargo]
495			switch op.kind {
496			case Load:
497				h := cloneHold(op.target)
498				h.cargo[c.id] = c.weight
499				if err := addWeight(h, c.weight, c.id); err != nil {
500					return nil, nil, err
501				}
502			case Unload:
503				h := cloneHold(c.hold)
504				delete(h.cargo, c.id)
505				if err := addWeight(h, -c.weight, c.id); err != nil {
506					return nil, nil, err
507				}
508			case Move:
509				src := cloneHold(c.hold)
510				delete(src.cargo, c.id)
511				if err := addWeight(src, -c.weight, c.id); err != nil {
512					return nil, nil, err
513				}
514				dst := cloneHold(op.target)
515				dst.cargo[c.id] = c.weight
516				if err := addWeight(dst, c.weight, c.id); err != nil {
517					return nil, nil, err
518				}
519			}
520		}
521		return staging, touched, nil
522	}
523	
524	// validateHold 校验一个推演舱位的终态重量与混装限制。
525	func validateHold(h *holdRec, cargos map[string]*cargoRec) error {
526		// 以清单重新求和，确保 used 与货物明细一致且均为非负。
527		var sum int64
528		ids := make([]string, 0, len(h.cargo))
529		for id := range h.cargo {
530			ids = append(ids, id)
531		}
532		sort.Strings(ids)
533		for _, id := range ids {
534			w := h.cargo[id]
535			if w <= 0 {
536				return &AdjustmentError{Reason: "overflow", Kind: "hold", ID: h.id}
537			}
538			v, overflow := addInt64(sum, w)
539			if overflow {
540				return &AdjustmentError{Reason: "overflow", Kind: "hold", ID: h.id}
541			}
542			sum = v
543		}
544		if sum > h.capacity {
545			return &AdjustmentError{Reason: "over_capacity", Kind: "hold", ID: h.id}
546		}
547	
548		// 混装：同一目的地可共舱；存在不同目的地时，所有货物都必须允许混装。
549		destSet := make(map[string]bool)
550		allMixable := true
551		for _, id := range ids {
552			c := cargos[id]
553			destSet[c.destination] = true
554			if !c.mixable {
555				allMixable = false
556			}
557		}
558		if len(destSet) > 1 && !allMixable {
559			return &AdjustmentError{Reason: "mixed_destination", Kind: "hold", ID: h.id}
560		}
561		return nil
562	}
563	
564	// sameContent 判断已保存结果与新提交的操作集合是否内容相同。
565	func sameContent(saved []CargoMove, ops []normOp) bool {
566		if len(saved) != len(ops) {
567			return false
568		}
569		// 以货物编号为键比较操作种类与目标舱位；每件货物至多一项。
570		want := make(map[string]normOp, len(ops))
571		for _, op := range ops {
572			want[op.cargo] = op
573		}
574		for _, m := range saved {
575			op, ok := want[m.CargoID]
576			if !ok {
577				return false
578			}
579			var target string
580			var kind OpKind
581			if !m.From.Loaded && m.To.Loaded {
582				kind = Load
583				target = m.To.HoldID
584			} else if m.From.Loaded && !m.To.Loaded {
585				kind = Unload
586			} else if m.From.Loaded && m.To.Loaded {
587				kind = Move
588				target = m.To.HoldID
589			} else {
590				return false // 未装载到未装载不是合法操作
591			}
592			if kind != op.kind || target != op.target {
593				return false
594			}
595		}
596		return true
597	}
598	
599	func locOf(hold string) Location {
600		if hold == "" {
601			return Location{}
602		}
603		return Location{HoldID: hold, Loaded: true}
604	}
605	
606	// addInt64 返回 a+b，并报告是否溢出 int64 范围。
607	func addInt64(a, b int64) (int64, bool) {
608		sum := a + b
609		if b > 0 && sum < a {
610			return 0, true
611		}
612		if b < 0 && sum > a {
613			return 0, true
614		}
615		return sum, false
616	}
617	
618	func cloneResult(r AdjustmentResult) AdjustmentResult {
619		cp := AdjustmentResult{AdjustmentID: r.AdjustmentID}
620		if r.Moves != nil {
621			cp.Moves = append([]CargoMove(nil), r.Moves...)
622		}
623		if r.HoldWeights != nil {
624			cp.HoldWeights = append([]HoldWeight(nil), r.HoldWeights...)
625		}
626		return cp
627	}
628	
629	// GetHold 按编号查看舱位的承重、已用、剩余重量及货物清单。货物清单按
630	// 编号字典序排列；返回值为独立快照。舱位不存在时返回包装 ErrNotFound 的
631	// *ReferenceError。
632	func (s *System) GetHold(id string) (*HoldView, error) {
633		norm, ok := normalizeID(id)
634		if !ok {
635			return nil, &ReferenceError{Kind: "hold", ID: norm}
636		}
637		s.mu.Lock()
638		defer s.mu.Unlock()
639		h, exists := s.holds[norm]
640		if !exists {
641			return nil, &ReferenceError{Kind: "hold", ID: norm}
642		}
643		return holdViewOf(h), nil
644	}
645	
646	// GetCargo 按编号查看货物信息与当前位置（未装载时 Location.Loaded 为
647	// false）。返回值为独立快照。货物不存在时返回包装 ErrNotFound 的
648	// *ReferenceError。
649	func (s *System) GetCargo(id string) (*CargoInfo, error) {
650		norm, ok := normalizeID(id)
651		if !ok {
652			return nil, &ReferenceError{Kind: "cargo", ID: norm}
653		}
654		s.mu.Lock()
655		defer s.mu.Unlock()
656		c, exists := s.cargos[norm]
657		if !exists {
658			return nil, &ReferenceError{Kind: "cargo", ID: norm}
659		}
660		return &CargoInfo{
661			ID:          c.id,
662			Weight:      c.weight,
663			Destination: c.destination,
664			Mixable:     c.mixable,
665			Location:    locOf(c.hold),
666		}, nil
667	}
668	
669	// Holds 返回全部舱位视图，按编号字典序排列；各视图均为独立快照。
670	func (s *System) Holds() []HoldView {
671		s.mu.Lock()
672		defer s.mu.Unlock()
673		ids := make([]string, 0, len(s.holds))
674		for id := range s.holds {
675			ids = append(ids, id)
676		}
677		sort.Strings(ids)
678		out := make([]HoldView, 0, len(ids))
679		for _, id := range ids {
680			out = append(out, *holdViewOf(s.holds[id]))
681		}
682		return out
683	}
684	
685	// Cargos 返回全部货物信息，按编号字典序排列；各项均为独立快照。
686	func (s *System) Cargos() []CargoInfo {
687		s.mu.Lock()
688		defer s.mu.Unlock()
689		ids := make([]string, 0, len(s.cargos))
690		for id := range s.cargos {
691			ids = append(ids, id)
692		}
693		sort.Strings(ids)
694		out := make([]CargoInfo, 0, len(ids))
695		for _, id := range ids {
696			c := s.cargos[id]
697			out = append(out, CargoInfo{
698				ID:          c.id,
699				Weight:      c.weight,
700				Destination: c.destination,
701				Mixable:     c.mixable,
702				Location:    locOf(c.hold),
703			})
704		}
705		return out
706	}
707	
708	func holdViewOf(h *holdRec) *HoldView {
709		refs := make([]CargoRef, 0, len(h.cargo))
710		for id, w := range h.cargo {
711			refs = append(refs, CargoRef{ID: id, Weight: w})
712		}
713		sort.Slice(refs, func(i, j int) bool { return refs[i].ID < refs[j].ID })
714		return &HoldView{ID: h.id, Capacity: h.capacity, Used: h.used, Cargo: refs}
715	}
716

